1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
RDMA/umad: Reject negative data_len in ib_umad_write

ib_umad_write computes data_len from user-controlled count and the
MAD header sizes. With a mismatched user MAD header size and RMPP
header length, data_len can become negative and reach ib_create_send_mad().
This can make the padding calculation exceed the segment size and trigger
an out-of-bounds memset in alloc_send_rmpp_list().

Add an explicit check to reject negative data_len before creating the
send buffer.

KASAN splat:
[  211.363464] BUG: KASAN: slab-out-of-bounds in ib_create_send_mad+0xa01/0x11b0
[  211.364077] Write of size 220 at addr ffff88800c3fa1f8 by task spray_thread/102
[  211.365867] ib_create_send_mad+0xa01/0x11b0
[  211.365887] ib_umad_write+0x853/0x1c80

Fixes: 2be8e3ee8efd ("IB/umad: Add P_Key index support")
Signed-off-by: YunJe Shin <ioerts@kookmin.ac.kr>
Link: https://patch.msgid.link/20260203100628.1215408-1-ioerts@kookmin.ac.kr
Signed-off-by: Leon Romanovsky <leon@kernel.org>

Here is the root cause:
The bug occurs because in `ib_umad_write`, `data_len` is computed as `count - hdr_size(file) - hdr_len` using a signed `int`. When the sum of header sizes exceeds the user-supplied `count`, the result becomes negative. This negative value is then passed to `ib_create_send_mad`, which expects an unsigned type, causing implicit conversion to a very large positive number. This oversized value leads to incorrect padding calculations in `alloc_send_rmpp_list`, resulting in an out-of-bounds `memset`.

Here is the patch:

 static ssize_t ib_umad_write(struct file *filp, const char __user *buf,
 			     size_t count, loff_t *pos)
 {
 	struct ib_umad_file *file = filp->private_data;
 	struct ib_rmpp_mad_hdr *rmpp_mad_hdr;
 	struct ib_umad_packet *packet;
 	struct ib_mad_agent *agent;
 	struct rdma_ah_attr ah_attr;
 	struct ib_ah *ah;
 	__be64 *tid;
-	int ret, data_len, hdr_len, copy_offset, rmpp_active;
+	int ret, hdr_len, copy_offset, rmpp_active;
+	size_t data_len;
 	u8 base_version;

 	if (count < hdr_size(file) + IB_MGMT_RMPP_HDR)
 		return -EINVAL;

 	packet = kzalloc(sizeof(*packet) + IB_MGMT_RMPP_HDR, GFP_KERNEL);
 	if (!packet)
 		return -ENOMEM;

 	if (copy_from_user(&packet->mad, buf, hdr_size(file))) {
 		ret = -EFAULT;
 		goto err;
 	}

 	if (packet->mad.hdr.id >= IB_UMAD_MAX_AGENTS) {
 		ret = -EINVAL;
 		goto err;
 	}

 	buf += hdr_size(file);

 	if (copy_from_user(packet->mad.data, buf, IB_MGMT_RMPP_HDR)) {
 		ret = -EFAULT;
 		goto err;
 	}

 	mutex_lock(&file->mutex);

 	trace_ib_umad_write(file, &packet->mad.hdr,
 			    (struct ib_mad_hdr *)&packet->mad.data);

 	agent = __get_agent(file, packet->mad.hdr.id);
 	if (!agent) {
 		ret = -EIO;
 		goto err_up;
 	}

 	memset(&ah_attr, 0, sizeof ah_attr);
 	ah_attr.type = rdma_ah_find_type(agent->device,
 					 file->port->port_num);
 	rdma_ah_set_dlid(&ah_attr, be16_to_cpu(packet->mad.hdr.lid));
 	rdma_ah_set_sl(&ah_attr, packet->mad.hdr.sl);
 	rdma_ah_set_path_bits(&ah_attr, packet->mad.hdr.path_bits);
 	rdma_ah_set_port_num(&ah_attr, file->port->port_num);
 	if (packet->mad.hdr.grh_present) {
 		rdma_ah_set_grh(&ah_attr, NULL,
 				be32_to_cpu(packet->mad.hdr.flow_label),
 				packet->mad.hdr.gid_index,
 				packet->mad.hdr.hop_limit,
 				packet->mad.hdr.traffic_class);
 		rdma_ah_set_dgid_raw(&ah_attr, packet->mad.hdr.gid);
 	}

 	ah = rdma_create_user_ah(agent->qp->pd, &ah_attr, NULL);
 	if (IS_ERR(ah)) {
 		ret = PTR_ERR(ah);
 		goto err_up;
 	}

 	rmpp_mad_hdr = (struct ib_rmpp_mad_hdr *)packet->mad.data;
 	hdr_len = ib_get_mad_data_offset(rmpp_mad_hdr->mad_hdr.mgmt_class);

 	if (ib_is_mad_class_rmpp(rmpp_mad_hdr->mad_hdr.mgmt_class)
 	    && ib_mad_kernel_rmpp_agent(agent)) {
 		copy_offset = IB_MGMT_RMPP_HDR;
 		rmpp_active = ib_get_rmpp_flags(&rmpp_mad_hdr->rmpp_hdr) &
 						IB_MGMT_RMPP_FLAG_ACTIVE;
 	} else {
 		copy_offset = IB_MGMT_MAD_HDR;
 		rmpp_active = 0;
 	}

 	base_version = ((struct ib_mad_hdr *)&packet->mad.data)->base_version;
-	data_len = count - hdr_size(file) - hdr_len;
+	if (check_sub_overflow(count, hdr_size(file) + hdr_len, &data_len)) {
+		ret = -EINVAL;
+		goto err_ah;
+	}
 	packet->msg = ib_create_send_mad(agent,
 					 be32_to_cpu(packet->mad.hdr.qpn),
 					 packet->mad.hdr.pkey_index, rmpp_active,
 					 hdr_len, data_len, GFP_KERNEL,
 					 base_version);
 	if (IS_ERR(packet->msg)) {
 		ret = PTR_ERR(packet->msg);
 		goto err_ah;
 	}

 	packet->msg->ah		= ah;
 	packet->msg->timeout_ms = packet->mad.hdr.timeout_ms;
 	packet->msg->retries	= packet->mad.hdr.retries;
 	packet->msg->context[0] = packet;

 	/* Copy MAD header.  Any RMPP header is already in place. */
 	memcpy(packet->msg->mad, packet->mad.data, IB_MGMT_MAD_HDR);

 	if (!rmpp_active) {
 		if (copy_from_user(packet->msg->mad + copy_offset,
 				   buf + copy_offset,
 				   hdr_len + data_len - copy_offset)) {
 			ret = -EFAULT;
 			goto err_msg;
 		}
 	} else {
 		ret = copy_rmpp_mad(packet->msg, buf);
 		if (ret)
 			goto err_msg;
 	}

 	/*
 	 * Set the high-order part of the transaction ID to make MADs from
 	 * different agents unique, and allow routing responses back to the
 	 * original requestor.
 	 */
 	if (!ib_response_mad(packet->msg->mad)) {
 		tid = &((struct ib_mad_hdr *) packet->msg->mad)->tid;
 		*tid = cpu_to_be64(((u64) agent->hi_tid) << 32 |
 				   (be64_to_cpup(tid) & 0xffffffff));
 		rmpp_mad_hdr->mad_hdr.tid = *tid;
 	}

 	if (!ib_mad_kernel_rmpp_agent(agent)
 	    && ib_is_mad_class_rmpp(rmpp_mad_hdr->mad_hdr.mgmt_class)
 	    && (ib_get_rmpp_flags(&rmpp_mad_hdr->rmpp_hdr) & IB_MGMT_RMPP_FLAG_ACTIVE)) {
 		spin_lock_irq(&file->send_lock);
 		list_add_tail(&packet->list, &file->send_list);
 		spin_unlock_irq(&file->send_lock);
 	} else {
 		spin_lock_irq(&file->send_lock);
 		ret = is_duplicate(file, packet);
 		if (!ret)
 			list_add_tail(&packet->list, &file->send_list);
 		spin_unlock_irq(&file->send_lock);
 		if (ret) {
 			ret = -EINVAL;
 			goto err_msg;
 		}
 	}

 	ret = ib_post_send_mad(packet->msg, NULL);
 	if (ret)
 		goto err_send;

 	mutex_unlock(&file->mutex);
 	return count;

 err_send:
 	dequeue_send(file, packet);
 err_msg:
 	ib_free_send_mad(packet->msg);
 err_ah:
 	rdma_destroy_ah(ah, RDMA_DESTROY_AH_SLEEPABLE);
 err_up:
 	mutex_unlock(&file->mutex);
 err:
 	kfree(packet);
 	return ret;
 }



